function readCareBlockTitleText(el) {
    if (!el) return '';
    var text = '';
    var i, node;
    for (i = 0; i < el.childNodes.length; i++) {
        node = el.childNodes[i];
        if (node.nodeType === 3) {
            text += node.nodeValue;
        } else if (node.nodeType === 1) {
            if (node.classList && node.classList.contains('dot')) continue;
            text += node.textContent || '';
        }
    }
    return text.replace(/^\s+|\s+$/g, '');
}

function registerCareBlockTitleType(ed) {
    var domc = ed.DomComponents;
    domc.addType('tc-care-block-title', {
        extend: 'text',
        isComponent: function (el) {
            if (el && el.tagName === 'H3' && el.classList && el.classList.contains('care-block-title')) {
                return { type: 'tc-care-block-title', content: readCareBlockTitleText(el) };
            }
        },
        model: {
            defaults: {
                tagName: 'h3',
                classes: ['care-block-title'],
                droppable: false
            }
        }
    });
}

function getCareBlockTitleTextFromComponent(component) {
    if (!component) return '';
    var el = component.getEl ? component.getEl() : null;
    if (el) return readCareBlockTitleText(el);
    return String(component.get('content') || '').replace(/^\s+|\s+$/g, '');
}

function normalizeCareBlockTitles() {
    if (!editor) return;

    var items = editor.getWrapper().find('h3.care-block-title');
    if (!items || !items.length) return;

    var changed = false;
    var i, item, parent, collection, index, text, children;

    for (i = items.length - 1; i >= 0; i--) {
        item = items[i];
        if (String(item.get('type') || '') === 'tc-care-block-title') {
            children = item.components ? item.components() : null;
            if (children && children.length) {
                text = getCareBlockTitleTextFromComponent(item);
                item.components(text);
                changed = true;
            }
            continue;
        }

        parent = item.parent();
        if (!parent || !parent.components) continue;

        collection = parent.components();
        index = collection.indexOf(item);
        text = getCareBlockTitleTextFromComponent(item);
        collection.add({
            type: 'tc-care-block-title',
            content: text
        }, { at: index });
        item.remove();
        changed = true;
    }

    if (changed && !hydrating) markDirty();
}

